/**
 * codex-data.js —— 内置种族条目
 *
 * 2026-11-06 晚大转向：幻想种族先收起来（141 条清单搁置），内置改做现实里常见的动物。
 * 每种动物做两条（她定的）：① 兽形＝现实里那种动物；② 亚人形态＝人形带这种动物的特征。
 * 另外按计划留一层：**大类 → 具体种类**（狗 → 边牧 / 德牧），具体种类只写外观差异，
 * 繁殖数据借大类那一条（`borrowFrom`）。只做两层，不套三层以上。
 *
 * 原来 42 条幻想条目的全文已归档到仓库外：
 *   工作区「种族图鉴-幻想种族-归档-20261106.md」（人看）
 *   工作区「种族图鉴-幻想种族-归档-20261106.json」（可以直接走「导入图鉴」导回来）
 * ⚠️ 归档文件不在仓库里（那是素材，不是插件内容）；这里只留当前要用的条目 ✓
 *
 * 亚人形态怎么填（她 2026-11-06 定的方向）：
 *   · 外观是人形，带这种动物的特征（耳朵、尾巴、羽、角、斑纹）✓
 *   · 繁殖往动物那边靠（2026-11-06 晚定的口径）：孕期、生育方式、一窝几只或几枚
 *     都按现实里那种动物来，单位跟着换
 *   · 性别分档、混血折算不填的借人类那一条（`borrowFrom: 'bi-human'`）；填了就接管 ✓
 *
 * 四段正文的分工（她 2026-11-06 定的，别写串）：
 *   简单介绍 / 生理 / 繁殖受孕 / 自由补充 —— 骰值分档、概率、孕期天数只进数值表与繁殖段
 *
 * ⚠️ 内置条目由代码提供，玩家改过的部分存在设置里（见 codex.js 的覆盖）
 *    这里**不许**写任何玩家的数据（示例角色 / 她的设定都不行 ✗）
 */

