/** 一条内置条目（字段没写的就留空，补全交给 normalizeEntry ✓） */
function E(o) {
    return {
        id: o.id,
        name: o.name,
        aliases: o.aliases || [],
        cat: o.cat,
        species: o.species || '',
        source: o.source,
        intro: o.intro || '',
        physio: o.physio || '',
        repro: o.repro || '',
        extra: o.extra || '',
        borrowFrom: o.borrowFrom || '',
        // ★ 2026-11-08：性特征（没写的条目留 undefined，normalizeEntry 补空 ✓）
        sexTrait: o.sexTrait,
        stages: o.stages || [],
        notes: o.notes || '',
    };
}

// ★★ 2026-11-08：内置条目的「泌乳」预填。
//
// 口径（她 2026-11-08 定的，并且当场纠正过一次）：
//   · **不能按生育方式推**：卵生不等于没奶（鸭嘴兽卵生也产奶）⇒ 只看这一族的原型；
//   · 亚人（人形身体）一律照人类写，可以产奶 ✓
//   · 兽人与兽形按原型：哺乳类有乳腺乳；鸽 / 企鹅这类是嗉囊乳、食道乳（不是乳腺，
//     也没有按天算的奶量）；爬行 / 鱼 / 两栖 / 虫 / 头足 / 无血肉的没有；
//   · 幻想族按原型套，套不出来的留空（＝按设定与剧情，插件不替玩家编这一族的身体）。
const MILK_MAMMAL = '有（乳腺乳）';
const MILK_CROP = '有（嗉囊乳这类）';
const MILK_NONE = '无';

/** 按种类给：哺乳类有奶；鸽 / 企鹅有嗉囊乳；其余没有 */
const MILK_BY_SPECIES = {
    pig: MILK_MAMMAL, dog: MILK_MAMMAL, cat: MILK_MAMMAL, horse: MILK_MAMMAL,
    rabbit: MILK_MAMMAL, rat: MILK_MAMMAL, elephant: MILK_MAMMAL, cattle: MILK_MAMMAL,
    sheep: MILK_MAMMAL, wolf: MILK_MAMMAL, tiger: MILK_MAMMAL, bear: MILK_MAMMAL,
    leopard: MILK_MAMMAL, lion: MILK_MAMMAL, monkey: MILK_MAMMAL, ape: MILK_MAMMAL,
    lemur: MILK_MAMMAL, fox: MILK_MAMMAL, deer: MILK_MAMMAL, cetacean: MILK_MAMMAL,
    pigeon: MILK_CROP, penguin: MILK_CROP,
    chicken: MILK_NONE, duck: MILK_NONE, goose: MILK_NONE, raptor: MILK_NONE,
    turtle: MILK_NONE, snake: MILK_NONE, fish: MILK_NONE, insect: MILK_NONE,
    arthropod: MILK_NONE, cephalopod: MILK_NONE,
};

/** 没有种类或种类型幻想族时按名字判：这一批明确没有奶（无血肉 / 无固定形态 / 鱼形 / 蛇形 / 鸟形） */
const MILK_NONE_NAMES = new Set([
    '史莱姆', '触手', '人形器灵', '灵体器灵', '怪物器灵',
    '丧尸', '僵尸', '骷髅', '幽灵', '血肉魔像', '石魔像', '机械人', '仿生人', '帝江',
    '蜥蜴人', '八岐大蛇', '八岐大蛇兽人', '烛龙', '相柳', '巴蛇', '九婴', '肥遗',
    '龙', '鲲', '陵鱼',
    '凤凰', '朱雀', '鸾鸟', '青鸟', '三足金乌', '毕方', '重明鸟', '鸩',
]);

/** 名字判「有乳腺乳」的：兽形神兽（鹿形 / 兽形）＋ 有血肉的幻想族 */
const MILK_MAMMAL_NAMES = new Set([
    '兽人', '狼人', '食人魔', '巨魔', '哥布林',
    '麒麟', '獬豸', '九色鹿', '鹿蜀', '饕餮', '梼杌', '狰', '貔貅', '白泽', '穷奇',
    '修罗', '血海魔',
]);

/** 设定差异太大、内置不替玩家定的（留空 ＝ 按设定与剧情） */
const MILK_BY_SETTING_NAMES = new Set(['炽天使', '智天使', '座天使']);

/**
 * 这一条内置条目的泌乳预填值（空串 = 留空，按设定与剧情）。
 * 顺序：亚人照人类 → 按种类 → 按名字。
 */
function milkOfBuiltin(o) {
    if (o.milk) return o.milk;
    if (o.cat === 'kin') return MILK_MAMMAL;                 // 亚人是人形身体，照人类 ✓
    if (o.cat === 'human') return MILK_MAMMAL;
    if (MILK_BY_SPECIES[o.species]) return MILK_BY_SPECIES[o.species];
    const name = String(o.name || '');
    if (MILK_NONE_NAMES.has(name)) return MILK_NONE;
    if (MILK_MAMMAL_NAMES.has(name)) return MILK_MAMMAL;
    if (MILK_BY_SETTING_NAMES.has(name)) return '';
    return '';
}

// rowsOf 的入参就是条目自己（数值项直接写在 make 的入参上，读起来集中）✓
function make(o) {
    // ★ 2026-11-07：内置的混血组 / 品种从上面那两张表补（条目正文里不用逐条再写一遍 ✓）
    // ★ 2026-11-08：泌乳也按原型补（见上面 milkOfBuiltin 的口径 ✓）
    const spec = {
        ...o,
        breedGroup: o.breedGroup || BUILTIN_BREED_GROUP[o.id] || '',
        breed: o.breed || BUILTIN_BREED[o.id] || '',
        milk: o.milk || milkOfBuiltin(o),
    };
    const entry = E(spec);
    entry.rows = rowsOf(spec);
    return entry;
}

/**
 * 兽形那一条的共同默认：分类「动物」，种类（第二层）跟着编号推：bi-dog → 犬，bi-cattle → 牛 ✓
 * 具体种类（边牧 / 德牧）也挂在狗下面 ⇒ 自己传 species: 'dog' ✓
 */
function beast(o) {
    const slug = String(o.id || '').replace(/^bi-/, '');
    const species = o.species || ((slug === 'border-collie' || slug === 'german-shepherd') ? 'dog' : slug);
    return make({
        source: 'origin',
        scale: '天',
        sex: '1-50 雄，51-100 雌',
        twin: TWIN_NONE,
        ...o,
        cat: 'animal',
        species,
    });
}

/** 亚人那一条的共同默认：分类「亚人」，种类跟兽形同一个（bi-pig-kin → 猪）；
 *  刻度天、同卵不判；性别与混血留空借人类 ✓ */
function kin(o) {
    const species = o.species || String(o.id || '').replace(/^bi-/, '').replace(/-kin$/, '');
    return make({
        source: 'origin',
        scale: '天',
        twin: TWIN_NONE,
        sex: '1-50 男，51-100 女',
        ...o,
        cat: 'kin',
        species,
    });
}

/** 兽人 / 类人怪物：分类「兽人」，默认胎生、单位只、男 / 女、不判同卵。
 *  有对应动物的自己传 species（狗科兽人 → dog、狼妖 → wolf 这类）✓ */
function monster(o) {
    return make({
        source: 'origin',
        cat: 'beastkin',
        scale: '天',
        sex: '1-50 男，51-100 女',
        twin: TWIN_NONE,
        unit: '只',
        ...o,
    });
}

/** 幻想类亚人（不是从现实动物来的那条）：分类「亚人」，默认胎生、单位胎、男 / 女 */
function folk(o) {
    return make({
        source: 'origin',
        cat: 'kin',
        scale: '天',
        sex: '1-50 男，51-100 女',
        twin: TWIN_NONE,
        unit: '胎',
        ...o,
    });
}

