    // =======================================================================
    // 鲸豚类（统称）＋ 8 个品种，每个三份。2026-11-07
    //   ★ 亚人按她定的：人形，只加**耳鳍 ＋ 一条尾巴**，别的一律不加。
    //   ★ 兽人按她给的那份写：兽首人身、头顶喷气孔（陆地用口鼻呼吸，水下闭气）、
    //     橡胶质感的厚皮、指间蹼（只能划水，不能抓握）、背鳍、小腿后侧接横向尾鳍。
    //   ★ 这一族没有滞育：着床按全局（6 到 10 天），孕期从受孕算。
