// ★ 2026-11-08（规则剥离第一步）：周期长度按种类填**平均值**
//
// 口径（她 2026-11-08 定的）：
//   · 按资料给每个族填一个平均天数，人类 28 / 14 也是平均值、不是必须值；
//   · 没有月经 / 没有发情周期的族可以不填（鸟、鱼、爬行、昆虫、头足、诱导排卵的兔…）；
//   · 空着 = 跟全局（28 天），不是「这一族没有周期」；
//   · **兽形与兽人都按原型**（她 2026-11-08 定的：兽人按原型来）；
//     亚人是人形身体，按人类那套 28 / 14（不用动）✓
//
// 数据来源：家畜与实验动物的发情周期通用值（兽医 / 实验动物学教材口径）。
// ⚠️ 猫是诱导排卵、兔子是反射排卵：硬填一个排卵日不成立 ⇒ 排卵日那一格留空，
//    只填周期长度（主模型只照系统给的结果写，不会自己去算排卵）✓
const CYCLE_LEN_BY_SPECIES = {
    pig: 21,            // 猪：发情周期 18 到 24 天，平均 21
    cattle: 21,         // 牛：21
    sheep: 17,          // 羊：16 到 17
    horse: 21,          // 马：21（发情期 5 到 7 天）
    dog: 180,           // 狗：两次发情间隔 5 到 7 个月，平均半年
    cat: 21,            // 猫：季节内 2 到 3 周一个周期
    rat: 4,             // 鼠：4 到 5 天
    elephant: 112,      // 象：约 16 周
    monkey: 28,         // 猴：约 28
    ape: 33,            // 猿：约 33
    lemur: 30,          // 狐猴：约 30
    leopard: 21,        // 猫科三种：季节内约 3 周
    tiger: 21,
    lion: 21,
    wolf: 365,          // 一年一次发情
    fox: 365,
    deer: 365,
    bear: 365,
    cetacean: 365,
    rabbit: 16,         // 兔：发情周期约 16 天（诱导排卵，排卵日不填）
};

/** 改一条条目的单个数行（rows 是建条目时展开的，改值要直接动 rows ✓） */
function setNumRow(entry, key, n) {
    const row = (entry.rows || []).find((r) => r.key === key);
    if (row) { row.kind = 'number'; row.num = n; }
}

/** 改一条条目的下拉行（诱导排卵那种「交配后排卵」✓） */
function setSelectRow(entry, key, text) {
    const row = (entry.rows || []).find((r) => r.key === key);
    if (row) { row.kind = 'select'; row.text = text; }
}

/** 改一条条目的区间行（诱导排卵率 / 延迟✓） */
function setRangeRow(entry, key, min, max) {
    const row = (entry.rows || []).find((r) => r.key === key);
    if (row) { row.kind = 'range'; row.min = min; row.max = max; }
}

/** 改一条条目的文字行（发情季节存的是「一年里的位置」那一串 ✓） */
function setTextRow(entry, key, text) {
    const row = (entry.rows || []).find((r) => r.key === key);
    if (row) row.text = text;
}

for (const e of BUILTIN_CODEX) {
    // 兽形与兽人按原型；亚人（kin）不填 ⇒ 跟人类 28 / 14（她 2026-11-08 定的「亚人不用动」）
    if (e.cat !== 'animal' && e.cat !== 'beastkin') continue;
    const n = CYCLE_LEN_BY_SPECIES[e.species];
    if (n) setNumRow(e, 'cycle_len', n);
}

// ★ 2026-11-08：诱导排卵（交配后才排卵）的族 —— 兔与猫科。
//   这一批不再看「排卵日」，由插件在交配时掷一次（见 store 的 maybeInduceOvu）；
//   诱导排卵率与延迟都是**区间**，每次交配各掷一个；亚人照人类，不套原型 ✓
const INDUCED_OVU_BY_SPECIES = {
    rabbit: { rate: [80, 90], delay: [10, 13] },   // 兔：反射排卵，交配后 10 到 13 小时
    cat: { rate: [70, 85], delay: [24, 30] },      // 猫：交配后约 24 到 30 小时
    leopard: { rate: [70, 85], delay: [24, 30] },  // 猫科同理
    tiger: { rate: [70, 85], delay: [24, 30] },
    lion: { rate: [70, 85], delay: [24, 30] },
};
for (const e of BUILTIN_CODEX) {
    if (e.cat !== 'animal' && e.cat !== 'beastkin') continue;
    const spec = INDUCED_OVU_BY_SPECIES[e.species];
    if (!spec) continue;
    setSelectRow(e, 'ovu_mode', '交配后排卵');
    setRangeRow(e, 'ovu_rate', spec.rate[0], spec.rate[1]);
    setRangeRow(e, 'ovu_delay', spec.delay[0], spec.delay[1]);
}

// 人类：28 / 14（平均值；她可以在图鉴里改，也可以按人单独调）
{
    const h = BUILTIN_CODEX.find((e) => e.id === 'bi-human');
    if (h) {
        setNumRow(h, 'cycle_len', 28);
        setNumRow(h, 'cycle_ovu', 14);
        // ★ 2026-11-08（发情期第 0 批）：人类没有发情期（隐蔽排卵）⇒ 明确填「无」✓
        setSelectRow(h, 'estrus', '无');
    }
}

