// ★★ 2026-11-08（她指出的）：图鉴正文里不许出现「照 X 那一套」这种跨条目指代 ——
//   读的人（和模型）不知道 X 是什么，等于把一句废话塞进正文。
//   这里统一把前缀摘掉，剩下的句子自己就站得住（同族的写法各自写全）✓
{
    const PREFIX = /^[照按跟]\s*[^：:，。；\n]{0,12}?那一套\s*[：:；;，,]?\s*/;
    const strip = (v) => (typeof v === 'string' && v ? v.replace(PREFIX, '') : v);
    for (const e of BUILTIN_CODEX) {
        for (const f of ['intro', 'physio', 'repro', 'extra']) e[f] = strip(e[f]);
        if (e.sexTrait) for (const f of ['male', 'outer', 'clit']) e.sexTrait[f] = strip(e.sexTrait[f]);
        if (Array.isArray(e.stages)) for (const st of e.stages) st.text = strip(st.text);
    }
}

