//   （她定的口径：亚人与兽人都是人形身体，兽形才用原型的实际尺寸 ✓）
{
    const HUMAN = '尺寸按这个人形身体定，跟同样身高的普通人类男性同一档，不套原型的实际尺寸';
    const BEAST = '尺寸按这一族本体的实际体型定，同族里体格大的更大';
    for (const e of BUILTIN_CODEX) {
        const st = e.sexTrait;
        if (!st || !st.male) continue;
        let v = String(st.male);
        if (e.cat === 'animal') {
            v = v.replace(/尺寸按体型比例/g, BEAST).replace(/尺寸按人形身高比例/g, BEAST);
        } else {
            v = v.replace(/尺寸按人形身高比例[，,]\s*(?:不算长|比鹅的长)/g, HUMAN)
                .replace(/尺寸按体型比例[，,]\s*(?:不算长|比鹅的长)/g, HUMAN)
                .replace(/尺寸按人形身高比例/g, HUMAN)
                .replace(/尺寸按体型比例/g, HUMAN);
        }
        st.male = v;
    }
}

// ★★ 2026-11-08（她：这句完全没用，那是正文的选择，不是插件要去说的）：
//   「可以只用一侧，也可以两根一起用」删掉 —— 怎么用是写正文的人自己定的事，
//   插件只留结构事实（平时收在泄殖腔里、交配时伸出来）✓
{
    for (const e of BUILTIN_CODEX) {
        const st = e.sexTrait;
        if (!st || !st.male) continue;
        st.male = String(st.male)
            .replace(/[，,]\s*可以只用一侧，也可以两根一起用/g, '')
            .replace(/\s*可以只用一侧，也可以两根一起用/g, '');
    }
}
